import{_ as s,l as c,o as a,c as d,v as t,p,x as o,d as l,i,S as n}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"mprotect","description":"","frontmatter":{"title":"mprotect","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mprotect.md","filePath":"cs/mprotect.md","lastUpdated":1789023840000}'),m={name:"cs/mprotect.md"};function h(_,e,u,T,f,A){const r=c("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="mprotect" tabindex="-1">mprotect <a class="header-anchor" href="#mprotect" aria-label="Permalink to &quot;mprotect&quot;">​</a></h1><div class="epigraph"><p>已存在的虚区间可以改权限：读、写、执行的组合变了，页表项与 TLB 必须跟着变。</p><footer>—— 据 POSIX mprotect；Silberschatz 对保护域的整理</footer></div><p><a href="/cs/mmap">上一课</a>已经能把文件或匿名页接到 VMA。<a href="/cs/paging-vm">分页</a>的权限位在缺页时检查。<a href="/cs/user-kernel-split">用户/内核分裂</a>禁止用户给内核页加写。缺口是运行中<strong>改自己的用户页权限</strong>：JIT 要先写后执行，栈要 NX，调试器要临时可写。不是新的映射，是改已有映射。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若只能在 mmap 时定权限，代码生成器必须unmap 再 map，丢失内容或窗口不安全。<code>mprotect</code> 按页对齐改一段 VA 的 r/w/x。缺口：拆 VMA、改 PTE、<a href="/cs/tlb-shootdown">TLB shootdown</a>。把可写改成不可写可能触发后课 COW 已处理的逻辑；把不可执行改成可执行要受安全策略约束——本课只要求内核拒绝无意义组合，不讲攻击步骤。</p><p>本课不把 <code>pkey</code> 与内存保护键的全部 ISA 写完。</p><p><span class="marginnote"><code>madvise</code> 提示内核预读或可丢页，不改权限。<code>mincore</code> 查询哪些页在内存。本课合并：它们操作同一段 VMA，对象仍是区间，不是新的页表格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户给出区间与新 prot。内核按页对齐，必要时把原 VMA 劈成三段，中间段新权限。已存在的页改 PTE；未分配的页只改 VMA，下次<a href="/cs/page-fault-path">缺页路径</a>按新权限填。他核 TLB 必须 shootdown，否则仍按旧写位存储。失败返回 EACCES/ENOMEM，不留下半改的权限。</p>',9)),(a(),p(n,null,{default:o(()=>[i(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MP%5B%22mprotect%22%5D%20--%3E%20SPLIT%5B%22%E6%8B%86%E5%90%88%20VMA%22%5D%0A%20%20SPLIT%20--%3E%20PTE%5B%22%E6%94%B9%E5%B7%B2%E5%A1%AB%20PTE%22%5D%0A%20%20PTE%20--%3E%20SD%5B%22TLB%20shootdown%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>mprotect 让保护变成动态的：同一物理页在不同时刻对同一进程可写或不可写。这与文件模式位不同——那是后课 inode 上的 rwx，对象是文件；这里是虚存。W^X 策略（写与执行不同时）由用户或安全模块在调用时拒绝，不是 MMU 新周期。</p><p>不要重导页表 walker。只改权限位与 VMA 标志。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>userfaultfd</code> 与保护键的组合拳。不保证所有架构支持对文件共享映射随意加执行。区间必须页对齐；未对齐由内核上取整或报错，POSIX 有规定。下一课离开用户 VMA，问内核自己的物理页从哪来。</p><p>后课默认：用户可改已有映射的权限。内核分配 2^n 页块给页表与缓冲，下一课 buddy。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>mprotect 改 VMA 与 PTE 权限，并 shootdown。</li><li>未触碰的页只改区间描述，缺页时再生效。</li><li>内核页框分配器是 buddy 的缺口。</li><li>出处：POSIX.1 <code>mprotect</code>；Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>。</li></ul>',8))])}const S=s(m,[["render",h]]);export{E as __pageData,S as default};
